OLD_IMPORT = ('from tools.high_level_main_flows.cartridge_source_data '
    'import load_cartridge_source_data, project_cartridge_m68k_authorities')
NEW_IMPORT = ('from tools.high_level_main_flows.high_level_cartridge_source_data '
    'import load_cartridge_source_data')
OLD_CALL = ('load_cartridge_source_data(project_root, '
    'm68k_authorities=project_cartridge_m68k_authorities(), '
    'sound_native_root=sound_native_root, sound_logical_sources=logical, resource_manifest=sources)')
NEW_CALL = ('load_cartridge_source_data(project_root, '
    'm68k_native_root=_high_level_m68k_native_root, '
    'sound_native_root=sound_native_root, sound_logical_sources=logical, resource_manifest=sources)')


def _shape(node):
    return ast.dump(node, include_attributes=False)


def _entry_module(original, base_entry):
    """Change one source import/call, retaining the complete city AST inverse."""
    derived = base_entry(original)
    result = copy.deepcopy(derived)
    runs = [node for node in result.body if type(node) is ast.FunctionDef and node.name == 'run']
    if len(runs) != 1:
        raise Boundary('one complete fresh city construction function required')
    run = runs[0]
    old_import, new_import = ast.parse(OLD_IMPORT).body[0], ast.parse(NEW_IMPORT).body[0]
    old_call, new_call = ast.parse(OLD_CALL, mode='eval').body, ast.parse(NEW_CALL, mode='eval').body
    imports = [node for node in ast.walk(run)
        if type(node) is ast.ImportFrom and _shape(node) == _shape(old_import)]
    calls = [node for node in ast.walk(run)
        if type(node) is ast.Call and _shape(node) == _shape(old_call)]
    if len(imports) != 1 or len(calls) != 1:
        raise Boundary('exact original cartridge source import and complete call required')
    imports[0].module, imports[0].names = new_import.module, copy.deepcopy(new_import.names)
    calls[0].func = copy.deepcopy(new_call.func)
    calls[0].args, calls[0].keywords = copy.deepcopy(new_call.args), copy.deepcopy(new_call.keywords)
    inverse = copy.deepcopy(result)
    replacements = dict(imports=0, calls=0)
    for node in ast.walk(inverse):
        if type(node) is ast.ImportFrom and _shape(node) == _shape(new_import):
            node.module, node.names = old_import.module, copy.deepcopy(old_import.names)
            replacements['imports'] += 1
        elif type(node) is ast.Call and _shape(node) == _shape(new_call):
            node.func, node.args, node.keywords = (
                copy.deepcopy(old_call.func), copy.deepcopy(old_call.args), copy.deepcopy(old_call.keywords))
            replacements['calls'] += 1
    if replacements != dict(imports=1, calls=1) or _shape(inverse) != _shape(derived):
        raise Boundary('complete high-level city construction source inverse differs')
    return ast.fix_missing_locations(result)


def build_high_level_city_cold_driver(project_root, sound_native_root, sources, audio_root,
        chip_library, inputs, output, *, m68k_native_root, save_image, fm_pcm_sink, psg_pcm_sink):
    """Start the original cold lifetime from explicit high-level build outputs.

    This is a real game entry, not a check or an automatically supplied fixture.
    Calling it retains all existing finite input and fresh output requirements.
    No build tool runs here and failures never fall back to legacy assembly.
    """
    native_root = Path(m68k_native_root).resolve(strict=True)
    if not native_root.is_dir():
        raise ValueError('one explicit existing high-level M68K native build root required')
    entry, _ = city._loaded(city, '_city_entry_module', EXPECTED_CITY_ENTRY_AST)
    factory, _ = city._loaded(city, '_make_city_factory', EXPECTED_CITY_FACTORY_AST)
    original, _ = city._loaded(city, 'build_city_cold_driver', EXPECTED_CITY_BUILD_AST)

    def selected_entry(tree):
        if city._city_entry_module is not entry:
            raise Boundary('the complete original city entry transform was rebound')
        return _entry_module(tree, entry)

    factory_namespace = dict(vars(city))
    factory_namespace['_city_entry_module'] = selected_entry
    selected_factory = FunctionType(factory.__code__, factory_namespace,
        factory.__name__, factory.__defaults__, None)
    selected_factory.__kwdefaults__ = factory.__kwdefaults__

    def make_family(save, fm, psg):
        family = selected_factory(save, fm, psg)

        def with_source(profile):
            if city._make_city_factory is not factory:
                raise Boundary('the complete original city construction factory was rebound')
            program = family(profile)
            if '_high_level_m68k_native_root' in program.__globals__:
                raise Boundary('fresh high-level source choice must not shadow an existing binding')
            program.__globals__['_high_level_m68k_native_root'] = native_root
            program.__globals__['_live_contract']['high_level_cartridge_source'] = dict(
                source_selected_before_original_reset=True,
                complete_city_factory_and_builder_CodeTypes_retained=True,
                exact_cartridge_import_changes=1, exact_complete_cartridge_CALL_changes=1,
                m68k_native_root=str(native_root), legacy_assembly_fallback=False,
                source_producer=_selected_cartridge_source.__module__,
                original_checksum_and_copy_programs_retained=True,
                same_source_sound_compositor_and_save_device_chain=True,
                source_or_device_hot_swap=False, native_builds=0, hashes_computed=0,
                runtime_acceptance_claimed=False, formal_new_CODE_bytes=0)
            return program

        return with_source

    namespace = dict(vars(city))
    namespace['_make_city_factory'] = make_family
    builder = FunctionType(original.__code__, namespace, original.__name__, original.__defaults__, None)
    builder.__kwdefaults__ = original.__kwdefaults__
    return builder(project_root, sound_native_root, sources, audio_root, chip_library, inputs, output,
        save_image=save_image, fm_pcm_sink=fm_pcm_sink, psg_pcm_sink=psg_pcm_sink)
